BEGIN;

-- CreateEnum
CREATE TYPE "UsagePeriodKind" AS ENUM ('DAILY', 'MONTHLY');

-- CreateEnum
CREATE TYPE "ReservationStatus" AS ENUM ('RESERVED', 'ATTEMPTING', 'UNCERTAIN', 'CONFIRMED', 'RELEASED');

-- AlterTable
ALTER TABLE "User" ADD COLUMN     "usageBackfillVersion" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "usageCutoverAt" TIMESTAMP(3);

-- AlterTable
ALTER TABLE "Send" ADD COLUMN     "availableAt" TIMESTAMP(3),
ADD COLUMN     "claimToken" TEXT,
ADD COLUMN     "dispatchAttemptedAt" TIMESTAMP(3),
ADD COLUMN     "dispatchAttempts" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "dispatchGeneration" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN     "leaseExpiresAt" TIMESTAMP(3),
ADD COLUMN     "queueExpiresAt" TIMESTAMP(3);

-- AlterTable
ALTER TABLE "DeliveryReceipt" ADD COLUMN     "deliveryKey" TEXT;

-- CreateTable
CREATE TABLE "UsagePeriod" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "kind" "UsagePeriodKind" NOT NULL,
    "startsAt" TIMESTAMP(3) NOT NULL,
    "endsAt" TIMESTAMP(3) NOT NULL,
    "operationalEndsAt" TIMESTAMP(3) NOT NULL,
    "sent" INTEGER NOT NULL DEFAULT 0,
    "reserved" INTEGER NOT NULL DEFAULT 0,
    "importedSent" INTEGER NOT NULL DEFAULT 0,
    "importedReserved" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "UsagePeriod_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "UsageReservation" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "deliveryKey" TEXT NOT NULL,
    "sendId" TEXT,
    "dailyPeriodId" TEXT NOT NULL,
    "monthlyPeriodId" TEXT NOT NULL,
    "status" "ReservationStatus" NOT NULL DEFAULT 'RESERVED',
    "chargedAt" TIMESTAMP(3),
    "confirmedAt" TIMESTAMP(3),
    "releasedAt" TIMESTAMP(3),
    "claimToken" TEXT,
    "leaseExpiresAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "UsageReservation_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "UsageImportEvidence" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "sourceKey" TEXT NOT NULL,
    "deliveryKey" TEXT,
    "chargedAt" TIMESTAMP(3) NOT NULL,
    "timestampSource" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "UsageImportEvidence_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "UsagePeriod_userId_kind_startsAt_operationalEndsAt_idx" ON "UsagePeriod"("userId", "kind", "startsAt", "operationalEndsAt");

-- CreateIndex
CREATE UNIQUE INDEX "UsagePeriod_userId_key_key" ON "UsagePeriod"("userId", "key");

-- CreateIndex
CREATE UNIQUE INDEX "UsagePeriod_id_userId_key" ON "UsagePeriod"("id", "userId");

-- CreateIndex
CREATE UNIQUE INDEX "UsageReservation_deliveryKey_key" ON "UsageReservation"("deliveryKey");

-- CreateIndex
CREATE UNIQUE INDEX "UsageReservation_sendId_key" ON "UsageReservation"("sendId");

-- CreateIndex
CREATE INDEX "UsageReservation_userId_status_chargedAt_idx" ON "UsageReservation"("userId", "status", "chargedAt");

-- CreateIndex
CREATE INDEX "UsageReservation_userId_dailyPeriodId_status_idx" ON "UsageReservation"("userId", "dailyPeriodId", "status");

-- CreateIndex
CREATE INDEX "UsageReservation_userId_monthlyPeriodId_status_idx" ON "UsageReservation"("userId", "monthlyPeriodId", "status");

-- CreateIndex
CREATE INDEX "UsageReservation_status_leaseExpiresAt_idx" ON "UsageReservation"("status", "leaseExpiresAt");

-- CreateIndex
CREATE UNIQUE INDEX "UsageImportEvidence_deliveryKey_key" ON "UsageImportEvidence"("deliveryKey");

-- CreateIndex
CREATE INDEX "UsageImportEvidence_userId_chargedAt_idx" ON "UsageImportEvidence"("userId", "chargedAt");

-- CreateIndex
CREATE UNIQUE INDEX "UsageImportEvidence_userId_sourceKey_key" ON "UsageImportEvidence"("userId", "sourceKey");

-- CreateIndex
CREATE INDEX "Send_status_deliveryState_availableAt_idx" ON "Send"("status", "deliveryState", "availableAt");

-- CreateIndex
CREATE INDEX "Send_deliveryState_leaseExpiresAt_idx" ON "Send"("deliveryState", "leaseExpiresAt");

-- CreateIndex
CREATE INDEX "Send_status_queueExpiresAt_idx" ON "Send"("status", "queueExpiresAt");

-- CreateIndex
CREATE UNIQUE INDEX "DeliveryReceipt_deliveryKey_key" ON "DeliveryReceipt"("deliveryKey");

-- AddForeignKey
ALTER TABLE "UsagePeriod" ADD CONSTRAINT "UsagePeriod_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "UsageReservation" ADD CONSTRAINT "UsageReservation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "UsageReservation" ADD CONSTRAINT "UsageReservation_sendId_fkey" FOREIGN KEY ("sendId") REFERENCES "Send"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "UsageReservation" ADD CONSTRAINT "UsageReservation_dailyPeriodId_userId_fkey" FOREIGN KEY ("dailyPeriodId", "userId") REFERENCES "UsagePeriod"("id", "userId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "UsageReservation" ADD CONSTRAINT "UsageReservation_monthlyPeriodId_userId_fkey" FOREIGN KEY ("monthlyPeriodId", "userId") REFERENCES "UsagePeriod"("id", "userId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "UsageImportEvidence" ADD CONSTRAINT "UsageImportEvidence_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Additive foundation only: do not populate accounting or change queued sends.
ALTER TABLE "User" ADD CONSTRAINT "User_usage_version_check"
  CHECK ("usageBackfillVersion" >= 0);
ALTER TABLE "Send" ADD CONSTRAINT "Send_dispatch_check"
  CHECK ("dispatchGeneration" >= 0 AND "dispatchAttempts" >= 0),
  ADD CONSTRAINT "Send_claim_check" CHECK (("claimToken" IS NULL) = ("leaseExpiresAt" IS NULL));
ALTER TABLE "UsagePeriod" ADD CONSTRAINT "UsagePeriod_bounds_check"
  CHECK ("startsAt" < "endsAt" AND "operationalEndsAt" >= "endsAt"),
  ADD CONSTRAINT "UsagePeriod_counters_check"
  CHECK (sent >= 0 AND reserved >= 0 AND "importedSent" >= 0 AND "importedReserved" >= 0
    AND "importedSent" <= sent AND "importedReserved" <= reserved),
  ADD CONSTRAINT "UsagePeriod_key_check" CHECK (length(btrim(key)) > 0);
ALTER TABLE "UsageReservation" ADD CONSTRAINT "UsageReservation_state_check" CHECK (
  (status = 'RESERVED' AND "chargedAt" IS NULL AND "confirmedAt" IS NULL AND "releasedAt" IS NULL AND "claimToken" IS NULL AND "leaseExpiresAt" IS NULL)
  OR (status IN ('ATTEMPTING', 'UNCERTAIN') AND "chargedAt" IS NOT NULL AND "confirmedAt" IS NULL AND "releasedAt" IS NULL AND "claimToken" IS NOT NULL AND "leaseExpiresAt" > "chargedAt")
  OR (status = 'CONFIRMED' AND "chargedAt" IS NOT NULL AND "confirmedAt" IS NOT NULL AND "releasedAt" IS NULL)
  OR (status = 'RELEASED' AND "releasedAt" IS NOT NULL AND "confirmedAt" IS NULL)
), ADD CONSTRAINT "UsageReservation_key_check" CHECK (length(btrim("deliveryKey")) > 0);
ALTER TABLE "UsageImportEvidence" ADD CONSTRAINT "UsageImportEvidence_source_check"
  CHECK (length(btrim("sourceKey")) > 0 AND "timestampSource" IN ('attemptedAt', 'sentAt'));

COMMIT;
